import { BrowserRouter, Routes, Route, Link } from 'react-router-dom';
import './App.css';
import Layout from './components/layout';
import LayoutAR from './components/layoutAR';

function App() {
  return (
    <BrowserRouter>
      <Route path="/" element={<Layout />} />
      <Route path="/ar" element={<LayoutAR />} />
    </BrowserRouter>
    // <Layout />
  );
}

export default App;
